import * as T from './three.module.js';
export function gardenCrop(g,index=0){const root=new T.Group();root.name=g.crop+' kitchen garden';const dummy=new T.Object3D(),count=18,vegetable=g.crop==='vegetables',sun=g.crop==='sunflower',green=new T.MeshStandardMaterial({color:vegetable?'#62884d':'#6d914b',roughness:.97});const stems=new T.InstancedMesh(vegetable?new T.SphereGeometry(1,10,8):new T.CylinderGeometry(.025,.035,sun?1.25:1.5,6),green,count),leaves=new T.InstancedMesh(new T.SphereGeometry(1,8,6),green,count*3),fruit=new T.InstancedMesh(sun?new T.SphereGeometry(1,12,8):new T.SphereGeometry(1,8,6),new T.MeshStandardMaterial({color:sun?'#d6ac42':vegetable?'#c47749':'#cbb461',roughness:.9}),count);root.add(stems,leaves,fruit);const centers=sun?new T.InstancedMesh(new T.SphereGeometry(1,10,8),new T.MeshStandardMaterial({color:'#70543b'}),count):null;if(centers)root.add(centers);
 for(let i=0;i<count;i++){const x=g.x+((i%3)-1)*.95,z=g.z+(Math.floor(i/3)-2.5)*.83,h=vegetable?.18:sun?1.25:1.5;dummy.rotation.set(0,0,0);dummy.position.set(x,.3+h/2,z);dummy.scale.set(vegetable?.25:1,vegetable?.16:1,vegetable?.25:1);dummy.updateMatrix();stems.setMatrixAt(i,dummy.matrix);for(let j=0;j<3;j++){dummy.position.set(x+Math.sin(j*2.4)*.15,.4+(vegetable?j*.05:j*.25),z+Math.cos(j*2.4)*.14);dummy.scale.set(vegetable?.23:.29,vegetable?.09:.035,.10);dummy.rotation.y=j*2.4;dummy.updateMatrix();leaves.setMatrixAt(i*3+j,dummy.matrix);}dummy.rotation.set(0,0,0);dummy.position.set(x,.3+(vegetable?.13:sun?h:h*.72),z+.04);dummy.scale.set(sun?.22:vegetable?.10:.075,sun?.22:vegetable?.08:.24,sun?.055:.08);dummy.updateMatrix();fruit.setMatrixAt(i,dummy.matrix);if(centers){dummy.position.z+=.045;dummy.scale.set(.13,.13,.035);dummy.updateMatrix();centers.setMatrixAt(i,dummy.matrix);}}
 for(const m of root.children)m.computeBoundingSphere();return root;}
